const STYLE = `You write ONE cozy bedtime story for a 9-YEAR-OLD GIRL (ages 9-12) in the "Boba Bedtime Stories" style.
TONE: warm, playful, silly, cozy — Roald Dahl meets a vibrant food market. Funny but kind. A laugh line in every major scene. A warm narrator who occasionally winks at the reader.
AGE SAFETY (critical): nothing genuinely scary, sad, violent, or dark. Gentle "cute" spookiness only (adorable friendly creatures). Any "getting eaten / becoming a treat" moment must be JOYFUL, proud, and celebratory — like a firework finally getting to light the sky — never frightening.
LENGTH: 1800-2000 words of story (not counting the header/blessing/prompts). Fun must start within the first ~150 words.
VOCAB: weave in 3-5 ${ROADMAP.languageNote ? '' : ''}local-language terms naturally. On FIRST use, format as **native term** (romanization) = English. The header's spotlight term is the key word.
CHARACTERS: give the main character a vivid physical description tied to its real food. Keep voices consistent with the bible below.

CHARACTER BIBLE for this collection:
${BIBLE}

${EXTRA}

OUTPUT: Use the Write tool to create the file at the EXACT path given, with EXACTLY this structure:

# Story <NUMBER>: <Title>

**Main Character:** <main character>
**Guest Characters:** <guests or "None">
**Setting:** <setting>
**Theme:** <theme>
**${SPOTLIGHT_LABEL}:** <native term> (<romanization>) = <english>

---

<opening hook ~150 words, instantly fun>

<main narrative ~1500 words: a clear adventure with a gentle problem and a warm resolution; humor throughout>

<warm ending — cozy and happy>

---

## Goodnight Blessing
<a soft, sleepy, warm closing — 3-6 sentences ending with "Goodnight.">

## AI Image Prompts
1. <key scene — detailed: warm whimsical storybook style, palette, character details, setting, mood/lighting>
2. <character portrait — the main character in a characteristic pose>
3. <closing scene — the cozy ending moment>

After writing the file, return the structured result.`

const RET = {
  type: 'object', additionalProperties: false,
  required: ['path','title','wordCount','ok'],
  properties: {
    path: { type: 'string' },
    title: { type: 'string' },
    wordCount: { type: 'integer' },
    ok: { type: 'boolean', description: 'true if the file was written successfully following all rules' },
  },
}

function prompt(s) {
  return `${STYLE}

WRITE THIS STORY NOW:
- Number: ${s.number}
- Title: ${s.title}
- Main Character: ${s.mainCharacter} (${s.type})
- Guest Characters: ${s.guests || 'None'}
- Setting: ${s.setting}
- Theme: ${s.theme}
- Spotlight term: ${s.spotlightTerm} (${s.spotlightRomanization}) = ${s.spotlightMeaning}
- Premise: ${s.premise}
- Arc: ${s.arc}
- EXACT file path to Write: ${s.path}

Write the full ~1800-2000 word story to that exact path, then return {path, title, wordCount, ok}.`
}

const results = await parallel(
  ROADMAP.stories.map(s => () =>
    agent(prompt(s), { label: `write:${s.number}-${s.slug}`, phase: 'Write stories', schema: RET })
      .then(r => r).catch(() => null)
  )
)

const ok = results.filter(Boolean)
const failed = ROADMAP.stories.filter((s,i) => !results[i]).map(s => s.number)
const short = ok.filter(r => (r.wordCount||0) < 1500).map(r => r.path)
log(`Taiwan: wrote ${ok.length}/${ROADMAP.stories.length}; failed=[${failed.join(',')}]; short(<1500w)=${short.length}`)
return { wrote: ok.length, total: ROADMAP.stories.length, failed, short }
